<script setup lang="ts">
import { computed } from 'vue'

type Kind = 'person' | 'car'
type Tone = 'enter' | 'leave'
type Direction = 'in' | 'out'

const props = withDefaults(defineProps<{
  kind?: Kind
  tone?: Tone
  direction?: Direction
}>(), {
  kind: 'person',
  tone: 'enter',
  direction: 'in',
})

const uid = Math.random().toString(36).slice(2, 8)

const palette = computed(() => {
  if (props.tone === 'enter') {
    return {
      bg1:    'rgba(77, 242, 255, 0.32)',
      bg2:    'rgba(0, 60, 130, 0.55)',
      stroke: 'rgba(77, 242, 255, 0.55)',
      arc1:   'rgba(77, 242, 255, 0.85)',
      arc2:   'rgba(0, 132, 255, 0.05)',
      fg2:    '#0083CC',
      dot:    '#FFFFFF',
    }
  }
  return {
    bg1:    'rgba(255, 198, 80, 0.32)',
    bg2:    'rgba(120, 60, 0, 0.55)',
    stroke: 'rgba(249, 185, 51, 0.55)',
    arc1:   'rgba(255, 233, 43, 0.85)',
    arc2:   'rgba(196, 132, 0, 0.05)',
    fg2:    '#A86E00',
    dot:    '#FFFFFF',
  }
})
</script>

<style lang="scss" scoped>
.icon-access-stat {
  display: block;
  width: 100%;
  height: 100%;
}
</style>
